import java.io.*;import java.math.*;import java.security.*;import java.text.*;import java.util.*;import java.util.concurrent.*;import java.util.regex.*;class Result {public static int beautifulDays(int i, int j, int k) {int count = 0;for (int day = i; day <= j; day++) {int reversed = reverse(day);if (Math.abs(day - reversed) % k == 0) {count++;}}return count;}private static int reverse(int n) {int rev = 0;while (n > 0) {rev = rev * 10 + (n % 10);n /= 10;}return rev;}}public class Solution {public static void main(String[] args) throws IOException {BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));BufferedWriter bufferedWriter = new BufferedWriter(new FileWriter(System.getenv("OUTPUT_PATH")));String[] firstMultipleInput = bufferedReader.readLine().replaceAll("\\s+$", "").split(" ");int i = Integer.parseInt(firstMultipleInput[0]);int j = Integer.parseInt(firstMultipleInput[1]);int k = Integer.parseInt(firstMultipleInput[2]);int result = Result.beautifulDays(i, j, k);bufferedWriter.write(String.valueOf(result));bufferedWriter.newLine();bufferedReader.close();bufferedWriter.close();}}